4.3 利用FlowAgent 自定义Multi-agent
核心还是围绕Graph的工作流框架来定制，流程如下：
五、实战：用Spring AI Alibaba实现Plan-Execute模式
5.1 流程示意
5.2 实现思路
1.整体分为三个阶段：1）规划，由PlanningAgent生成可执行的步骤；2）执行，分步骤选取ReactAgent并执行；3）总结，由SummaryAgent将上面每个步骤的内容聚合分析，给出总结性的结论。
2.每个Agent实现都是ReactAgent。
3.合理的利用Function Call，比如生成计划和步骤，以及每个步骤使用的Agent。
4.步骤之前需要进行上下文和状态传递，下一个Agent需要感知环境信息。
5.用合理的方式将上面的流程编排在一起。
5.3 实现方案
5.3.1 手动编排
示例代码：
/**
* Plan-Execute 模式简化示例
* 核心思想：先规划（Plan），再执行（Act），最后总结（Summarize）
*/
publicclassSimplifiedPlanningCoordinator {
/**
* Plan-Execute 模式的主入口
*
*
@param
laiContext 上下文信息
*
@return
完整的规划和执行结果
*/
public
Planning
execute
(Context context)
{
// 第一阶段：Planning - 生成执行计划
Planning
planning
=
generatePlanning(context);
// 第二阶段：Acting - 按计划执行步骤
executeSteps(planning, context);
// 第三阶段：Summarizing - 汇总结果
summarize(planning, context);
return
planning;
}
/**
* 阶段一：生成执行计划
* 根据用户输入，由 AI 生成结构化的执行步骤
*/
private
Planning
generatePlanning
(Context context)
{
// 步骤1: 创建 Planning Agent
// 这个 Agent 的职责是分析用户需求并制定执行计划
ReactAgent
planningAgent
=
reactAgentFactory.createReactAgent(
context,
"planning"
// Agent 名称
);
// 步骤2: 构建 Planning Prompt
// 提示词中包含：用户需求、可用的 Agent 列表、当前时间等信息
String
planningPrompt
=
buildPlanningPrompt(context);
// 步骤3: 调用 Planning Agent
// Agent 会分析需求，然后主动调用 PlanningTool 来创建计划
UserMessage
userMessage
=
new
UserMessage
(planningPrompt);
AssistantMessage
response
=
planningAgent.call(userMessage);
// 步骤4: 获取生成的计划
// PlanningTool 已经将计划保存到上下文中了
Planning
planning
=
getPlanningFromContext(context);
return
planning;
}
/**
* 阶段二：按计划执行各个步骤
* 这是 Act 阶段，每个步骤由特定的 Agent 负责执行
*/
privatevoidexecuteSteps(Planning planning, Context context){
List<PlanningStep> steps = planning.getSteps();
// 顺序执行每个步骤
for
(PlanningStep step : steps) {
// 1. 获取该步骤对应的 Agent
String
agentName
=
step.getAgent();
ReactAgent
agent
=
reactAgentFactory.createReactAgent(
context,
agentName
// Agent 名称
);
// 2. 构造该步骤的执行提示词
UserMessage
userMessage
=
buildStepPrompt(step, context);
// 3. 调用 Agent 执行
AssistantMessage
response
=
agent.call(userMessage);
// 4. 保存执行结果
step.setResult(response.getText());
step.markAsCompleted();
}
}
/**
* 阶段三：汇总所有步骤的执行结果
* 由专门的总结 Agent 将各步骤结果整合成最终答案
*/
privatevoidsummarize(Planning planning, Context context){
// 1. 收集所有步骤的执行结果
String
allStepsResults
=
collectAllResults(planning);
// 2. 构造总结提示词，包含所有步骤的执行结果
UserMessage
summaryPrompt
=
buildSummaryPrompt(allStepsResults, context);
// 3. 调用总结 Agent 生成最终结果
ReactAgentWrapper
summaryAgent
=
createSummaryAgent();
AssistantMessage
finalResult
=
summaryAgent.call(summaryPrompt);
// 4. 保存最终结果
context.setFinalResult(finalResult.getText());
}
/**
* 构建 Planning Prompt
* 这是让 AI 能够制定好计划的关键
*/
private
String
buildPlanningPrompt
(Context context)
{
// 1. 获取所有可用的 Agent 配置
List<AgentConfig> availableAgents = getAvailableAgents(context);
// 2. 构建 Agent 信息描述
StringBuilder
agentsInfo
=
new
StringBuilder
(
"可用的 Agent 列表：\n"
);
for
(AgentConfig agent : availableAgents) {
agentsInfo.append(
"- Agent 名称: "
).append(agent.getName()).append(
"\n"
);
agentsInfo.append(
"  描述: "
).append(agent.getDescription()).append(
"\n"
);
agentsInfo.append(
"  擅长: "
).append(agent.getCapabilities()).append(
"\n\n"
);
}
// 3. 组装完整提示词
String
prompt
=
String.format(
"""
你是一个任务规划专家。请根据用户的需求制定详细的执行计划。
用户需求：
%s
%s
请使用 PlanningTool 创建执行计划。计划应该：
1. 将复杂任务分解为多个可执行的步骤
2. 为每个步骤分配最合适的 Agent
3. 确保步骤之间的依赖关系合理
4. 步骤描述要清晰具体
""",
context.getUserInput(),
agentsInfo.toString()
);
return
prompt;
}
