/**
* Planning Tool 简化示例
* 这是一个供 AI 调用的工具，用于创建执行计划
*/
publicclassSimplifiedPlanningToolimplementsToolFunctionInterface<SimplifiedPlanningTool.PlanInput, String> {
@Override
public
String
getDescription
()
{
return
"用于创建和管理任务执行计划的工具"
;
}
/**
* Tool 的核心逻辑
* 当 AI 决定使用这个工具时，会调用此方法
*/
@Override
public
String
apply
(PlanInput input, ToolContext context)
{
// 1. 根据 AI 生成的计划内容创建 Planning 对象
Planning
planning
=
createPlanningFromInput(
context,
input.getTitle(),
input.getSteps()
);
// 2. 将计划保存到上下文中，供后续执行使用
